          '<table><thead><tr><th>Header 1</th><th>Header 2</th><th>Header 3</th></tr></thead>' +
          '<tbody><tr><td>Cell 1</td><td>Cell 2</td><td>Cell 3</td></tr>' +
          '<tr><td>Cell 4</td><td>Cell 5</td><td>Cell 6</td></tr></tbody></table>'
