function heading(opts) {
  const action = opts.actionHref && opts.actionLabel ? `
        <a class="gov-btn gov-btn--outline" href="${opts.actionHref}">${opts.actionLabel}</a>` : "";
  return `      <header class="gov-section-heading${action ? " gov-section-heading--with-action" : ""}">
        <div>
${opts.eyebrow ? `          <p class="gov-section-heading__eyebrow">${opts.eyebrow}</p>
` : ""}          <h2 class="gov-section-heading__title">${opts.title}</h2>
${opts.description ? `          <p class="gov-section-heading__description">${opts.description}</p>
` : ""}        </div>${action}
      </header>`;
}
